mapper.select:
/* selectReqList - Lee MS */
A.ESNTL_LINK_INST_SE_CD AS ESNTL_LINK_INST_SE_CD, A.OGDP_INST_DTL_SE_CD AS OGDP_INST_DTL_SE_CD, A.INST_NM AS LINK_INST_NM, TO_CHAR(A.FRST_REG_DT, 'YYYY-MM-DD') AS REG_YMD, DECODE(A.CMIT_MFCMM_ENTRST_YN, 'Y', '위촉', '미위촉') AS ENTRST_YN, DECODE(A.NOW_ACTVT_YN, 'Y', '예', '아니오') AS ACTVT_YN, B.INST_NM AS INST_NM, A.ESNTL_LINK_MNG_NO AS ESNTL_LINK_MNG_NO FROM ACA600 A, SAA000 B /* 통합기관(B), 통합기관(C) */ WHERE A.INST_NO = B.INST_NO AND A.NOW_ACTVT_YN LIKE #{ACTVT_YN}||'%' AND NVL(A.INST_NM, ' ') LIKE #{INST_NM}||'%' AND A.FRST_REG_DT >= TO_DATE(#{BGNG_YMD}||'000000', 'YYYYMMDDHH24MISS') AND A.FRST_REG_DT <= TO_DATE(#{END_YMD}||'235959', 'YYYYMMDDHH24MISS')
AND A.ESNTL_LINK_INST_SE_CD LIKE #{INST_SE}||'%'
AND A.ESNTL_LINK_INST_SE_CD IN ('1', '2')
/* 20230410_권한 쿼리_권한쿼리시작*/
/* 20230220_권한 쿼리_권한쿼리종료*/

/* selectYngbgsSurgList - Lee MS */
A.ESNTL_LINK_INST_SE_CD AS ESNTL_LINK_INST_SE_CD, A.OGDP_INST_DTL_SE_CD AS OGDP_INST_DTL_SE_CD, DECODE(A.SPRT_ORGNZT_PTCPTN_SE_CD, '2', A.INST_NM, '') AS LINK_INST_NM, DECODE(A.SPRT_ORGNZT_PTCPTN_SE_CD, '1', C##RG.DEC_B64(A.RPRSV_NM_ENCPT), '') AS RPRSV_NM, TO_CHAR(A.FRST_REG_DT, 'YYYY-MM-DD') AS REG_YMD, DECODE(A.CMIT_MFCMM_ENTRST_YN, 'Y', '위촉', '미위촉') AS ENTRST_YN, DECODE(A.NOW_ACTVT_YN, 'Y', '예', '아니오') AS ACTVT_YN, B.INST_NM AS INST_NM, A.ESNTL_LINK_MNG_NO AS ESNTL_LINK_MNG_NO FROM ACA600 A, SAA000 B /* 통합기관(B), 통합기관(C) */ WHERE A.INST_NO = B.INST_NO AND A.NOW_ACTVT_YN LIKE #{ACTVT_YN}||'%' AND NVL(A.INST_NM, ' ') LIKE #{INST_NM}||'%' AND A.FRST_REG_DT >= TO_DATE(#{BGNG_YMD}||'000000', 'YYYYMMDDHH24MISS') AND A.FRST_REG_DT <= TO_DATE(#{END_YMD}||'235959', 'YYYYMMDDHH24MISS')
AND A.ESNTL_LINK_INST_SE_CD LIKE #{INST_SE}||'%'
AND A.ESNTL_LINK_INST_SE_CD IN ('3', '4')
/* 20230410_권한 쿼리_권한쿼리시작*/
/* 20230220_권한 쿼리_권한쿼리종료*/

/* selectReqById - Lee MS */
SELECT A.ESNTL_LINK_MNG_NO AS ESNTL_LINK_MNG_NO, /* 필수연계기관구분코드 */ A.ESNTL_LINK_INST_SE_CD AS ESNTL_LINK_INST_SE_CD, /* 소속기관상세구분코드 */ A.OGDP_INST_DTL_SE_CD AS OGDP_INST_DTL_SE_CD, /* 지원조직참여구분코드 */ A.SPRT_ORGNZT_PTCPTN_SE_CD AS SPRT_ORGNZT_PTCPTN_SE_CD, /* 기관명 */
A.INST_NM AS INST_NM, C##RG.DEC_B64(A.RPRSV_NM_ENCPT) AS RPRSV_NM, A.JBTTL_NM AS JBTTL_NM, A.RPRS_TELNO AS RPRS_TELNO, A.INST_ADDR AS INST_ADDR, A.INST_DADDR AS INST_DADDR, A.HPGE_ADDR AS HPGE_ADDR,
A.LINK_CNCLS_BGNG_YMD AS LINK_CNCLS_BGNG_YMD, A.LINK_CNCLS_END_YMD AS LINK_CNCLS_END_YMD, A.NOW_ACTVT_YN AS NOW_ACTVT_YN, A.CMIT_MFCMM_ENTRST_YN AS CMIT_MFCMM_ENTRST_YN, A.YNGBGS_SPRT_RELM_CN AS YNGBGS_SPRT_RELM_CN, /* 청소년지원영역내용 */ A.ATFINO AS ATFINO, /* 첨부화일번호 */
A.PIC_NO AS PIC_NO, A.INST_NO AS INST_NO FROM ACA600 A WHERE A.ESNTL_LINK_MNG_NO = #{ESNTL_LINK_MNG_NO}
/* 기관명, 기관대표자명, 기관주소, 기관대표번호, 홈페이지*/

mapper.delete:

 /* deleteData - Lee  MS */

DELETE FROM ACA600 /* 필수연계기관 및 연계강화기관 */
WHERE ESNTL_LINK_MNG_NO = #{ESNTL_LINK_MNG_NO}
